window.PORTFOLIO_PAGE_TRANSLATIONS = [["DocPilot \u2014 Offline AI engineering-document toolkit \u00d7 LangGraph agent","DocPilot \u2014 \uc624\ud504\ub77c\uc778 AI \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ubb38\uc11c \ud234\ud0b7 \u00d7 LangGraph \uc5d0\uc774\uc804\ud2b8"],["\u2190 jinhyun an \u00b7 portfolio","\u2190 jinhyun an \u00b7 \ud3ec\ud2b8\ud3f4\ub9ac\uc624"],["Full-stack Document AI \u00b7 LangGraph Agent","\ud480\uc2a4\ud0dd \ubb38\uc11c AI \u00b7 LangGraph \uc5d0\uc774\uc804\ud2b8"],["An air-gapped document AI app,","\ud3d0\uc1c4\ub9dd\uc5d0\uc11c \ub3c4\ub294 \ubb38\uc11c AI \uc571\uc744,"],["evolved into a declarative agent","\uc120\uc5b8\uc801 \uc5d0\uc774\uc804\ud2b8\ub85c \uc9c4\ud654\uc2dc\ud0a4\ub2e4"],["DocPilot is an","DocPilot\uc740 \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1 \ubb38\uc11c(\uc0ac\uc591\u00b7\uacc4\uc57d\u00b7\uae30\uc220 \uac80\ud1a0)\ub97c \ub2e4\ub8e8\ub294"],["offline-first full-stack desktop web app","\uc624\ud504\ub77c\uc778 \uc9c0\ud5a5 \ud480\uc2a4\ud0dd \ub370\uc2a4\ud06c\ud1b1 \uc6f9\uc571"],[" for engineering documents (specifications, contracts and technical reviews). Built with FastAPI + React, it ships as a","\uc785\ub2c8\ub2e4. FastAPI + React\ub85c \ub9cc\ub4e4\uace0"],["single PyInstaller exe","PyInstaller \ub2e8\uc77c exe"],[" and calls LLMs through an OpenAI-compatible endpoint (OpenRouter by default). One principle \u2014 tools over tokens. Deterministic code handles calculations and validation; the LLM handles orchestration and narrative.","\ub85c \ubc30\ud3ec\ud558\uba70, LLM\uc740 OpenAI \ud638\ud658 \uc5d4\ub4dc\ud3ec\uc778\ud2b8(\uae30\ubcf8 OpenRouter)\ub85c \ud638\ucd9c\ud569\ub2c8\ub2e4. \uc6d0\uce59\uc740 \ud558\ub098 \u2014 tools over tokens. \uc22b\uc790\u00b7\uac80\uc99d\uc740 \uacb0\uc815\ub860\uc801 \ucf54\ub4dc\uac00 \ub2f4\ub2f9\ud558\uace0, LLM\uc740 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\uc158\uacfc \uc11c\uc220\ub9cc \ud569\ub2c8\ub2e4."],["GitHub repository \u2192","GitHub \ub808\ud3ec \u2192"],["LangGraph agent \u2192","LangGraph \uc5d0\uc774\uc804\ud2b8 \u2192"],["Context \u2014 abundant site documents, restricted networks","\ub9e5\ub77d \u2014 \ud604\uc7a5\uc758 \ubb38\uc11c\ub294 \ub9ce\uace0, \ub9dd\uc740 \ub2eb\ud600 \uc788\ub2e4"],["Specifications, contracts and technical-review documents on EPC and plant projects are voluminous and repetitive. Yet many sites prohibit external internet and cloud SaaS for security reasons. DocPilot addresses both constraints: (1) it chains four document stages (translate, analyze, review, write) in one app, and (2) installation and startup require only a","EPC/\ud50c\ub79c\ud2b8 \ud604\uc7a5\uc758 \uc0ac\uc591\u00b7\uacc4\uc57d\u00b7\uae30\uc220 \uac80\ud1a0 \ubb38\uc11c\ub294 \uc591\uc774 \ub9ce\uace0 \ubc18\ubcf5\uc801\uc785\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uc0c1\ub2f9\uc218 \ud604\uc7a5\uc740 \ubcf4\uc548\uc0c1 \uc678\ubd80 \uc778\ud130\ub137\u00b7\ud074\ub77c\uc6b0\ub4dc SaaS\ub97c \uc4f8 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c DocPilot\uc740 \ub450 \uc81c\uc57d\uc744 \ub3d9\uc2dc\uc5d0 \ud480\ub3c4\ub85d \uc124\uacc4\ud588\uc2b5\ub2c8\ub2e4. (1) \ubb38\uc11c \ucc98\ub9ac 4\ub2e8\uacc4(\ubc88\uc5ed\u00b7\ubd84\uc11d\u00b7\uac80\ud1a0\u00b7\uc791\uc131)\ub97c \ud55c \uc571\uc5d0\uc11c \uccb4\uc774\ub2dd\ud558\uace0, (2) \uc124\uce58\u00b7\uad6c\ub3d9\uc774"],["single executable + local server","\ub2e8\uc77c \uc2e4\ud589\ud30c\uc77c + \ub85c\uceec \uc11c\ubc84"],[" to run in a browser on an air-gapped network. Swap the LLM gateway to use the same app with an internal endpoint or OpenRouter.","\ub85c \ub05d\ub098 \ud3d0\uc1c4\ub9dd\uc5d0\uc11c\ub3c4 \ube0c\ub77c\uc6b0\uc800 \ud558\ub098\ub85c \ub3cc\uc544\uac11\ub2c8\ub2e4. LLM \uac8c\uc774\ud2b8\uc6e8\uc774\ub9cc \uad50\uccb4\ud558\uba74 \uc0ac\ub0b4\ub9dd\uc774\ub4e0 OpenRouter\ub4e0 \ub3d9\uc77c\ud558\uac8c \ubd99\uc2b5\ub2c8\ub2e4."],["This page presents the","\ubcf8 \ud398\uc774\uc9c0\ub294 \uc0ac\ub0b4 \uacbd\uc9c4\ub300\ud68c \ucd9c\ud488\uc791\uc744"],["anonymized public portfolio version","\uc775\uba85\ud654\ud558\uc5ec \uacf5\uac1c\ud55c \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ubc84\uc804"],[" of an internal competition entry. Production secrets, the internal gateway and customer data are excluded.","\uc744 \uae30\uc900\uc73c\ub85c \ud569\ub2c8\ub2e4. \uc2e4\uc81c \ud504\ub85c\ub355\uc158 \uc2dc\ud06c\ub9bf\u00b7\uc0ac\ub0b4 \uac8c\uc774\ud2b8\uc6e8\uc774\u00b7\uace0\uac1d \ub370\uc774\ud130\ub294 \uc81c\uc678\ud588\uc2b5\ub2c8\ub2e4."],["System \u2014 a full stack inside one exe","\uc2dc\uc2a4\ud15c \u2014 \ub2e8\uc77c exe \uc548\uc758 \ud480\uc2a4\ud0dd"],["The backend uses FastAPI + SQLite + Fernet (secret encryption); the frontend uses React 18 + Vite + TypeScript + Ant Design. FastAPI serves the frontend build as static assets. Packaged with PyInstaller onedir,","\ubc31\uc5d4\ub4dc\ub294 FastAPI + SQLite + Fernet(\uc2dc\ud06c\ub9bf \uc554\ud638\ud654), \ud504\ub860\ud2b8\uc5d4\ub4dc\ub294 React 18 + Vite + TypeScript + Ant Design\uc785\ub2c8\ub2e4. \ud504\ub860\ud2b8 \ube4c\ub4dc \uacb0\uacfc\ub97c FastAPI\uac00 \uc815\uc801 \uc11c\ube59\ud558\uace0, PyInstaller onedir\ub85c \ubb36\uc740"],[" starts a local server and opens the default browser automatically. The screenshot below shows a short specification clause translated in the actual app: an OpenRouter response in 1.9 seconds, displayed directly in the app UI.","\uac00 \ub85c\uceec \uc11c\ubc84\ub97c \ub744\uc6b4 \ub4a4 \uae30\ubcf8 \ube0c\ub77c\uc6b0\uc800\ub97c \uc790\ub3d9\uc73c\ub85c \uc5fd\ub2c8\ub2e4. \uc544\ub798\ub294 \uc2e4\uc81c \uc571\uc5d0\uc11c \ub2e8\ubb38(\uc0ac\uc591 \uc870\ud56d)\uc744 \ubc88\uc5ed\ud55c \ud654\uba74\uc785\ub2c8\ub2e4 \u2014 OpenRouter \uc751\ub2f5 1.9\ucd08, \uacb0\uacfc\ub294 \uadf8\ub300\ub85c \uc571 UI\uc5d0 \ud45c\uc2dc\ub429\ub2c8\ub2e4."],["DocPilot translation screen \u2014 a specification clause and its live translation result","DocPilot \ubc88\uc5ed \ud654\uba74 \u2014 \uc0ac\uc591 \uc870\ud56d\uc744 \uc785\ub825\ud558\uace0 \uc2e4\uc2dc\uac04 \ubc88\uc5ed \uacb0\uacfc\uac00 \ud45c\uc2dc\ub41c \ubaa8\uc2b5"],["Sentence-translation mode \u2014 an ASME B31.3 piping clause and the actual LLM translation. Connection status, model and active tasks appear at the top.","\ubb38\uc7a5 \ubc88\uc5ed \ubaa8\ub4dc \u2014 ASME B31.3 \ubc30\uad00 \uc0ac\uc591 \uc870\ud56d\uc744 \uc785\ub825\ud558\uace0 \uc2e4\uc81c LLM \ubc88\uc5ed \uacb0\uacfc\ub97c \ubc1b\uc740 \ud654\uba74. \uc0c1\ub2e8\uc5d0 \uc5f0\uacb0 \uc0c1\ud0dc\u00b7\ubaa8\ub378\u00b7\uc9c4\ud589 \uc911 \uc791\uc5c5\uc774 \ud45c\uc2dc\ub429\ub2c8\ub2e4."],["Four document modules \u2014 chaining analysis through deviation drafting","4\uac1c \ubb38\uc11c \ubaa8\ub4c8 \u2014 \ubd84\uc11d\uc5d0\uc11c Deviation \uc791\uc131\uae4c\uc9c0 \uccb4\uc774\ub2dd"],["Pipeline from document upload through Analyze, Review and Write","\ubb38\uc11c \uc5c5\ub85c\ub4dc\uc5d0\uc11c Analyze, Review, Write\ub85c \uc774\uc5b4\uc9c0\ub294 \ud30c\uc774\ud504\ub77c\uc778"],["Upload Excel / CSV","Excel / CSV \uc5c5\ub85c\ub4dc"],["Analyze (LLM per row)","Analyze (\ud589\ubcc4 LLM)"],["Review (review \u00b7 xlsx/pdf export)","Review (\uac80\ud1a0 \u00b7 xlsx/pdf export)"],["Write (draft Deviation List)","Write (Deviation List \uc791\uc131)"],["Stages light up sequentially when you scroll into this section. Translate operates independently of this pipeline, with column, whole-file and sentence modes.","\uc2a4\ud06c\ub864\ud574\uc11c \uc774 \uc139\uc158\uc5d0 \ub4e4\uc5b4\uc624\uba74 \ub2e8\uacc4\uac00 \uc21c\ucc28 \uc810\ub4f1\ub429\ub2c8\ub2e4. Translate\ub294 \uc704 \ud30c\uc774\ud504\ub77c\uc778\uacfc \ub3c5\ub9bd\uc801\uc73c\ub85c \uceec\ub7fc\u00b7\uc804\uccb4\ud30c\uc77c\u00b7\ub2e8\ubb38 3\ubaa8\ub4dc\ub97c \uc81c\uacf5\ud569\ub2c8\ub2e4."],["Translate","\ubc88\uc5ed(Translate)"],["\u2014 Translate columns, entire files (preserving sheets and structure), or individual sentences; retry only failed rows.","\u2014 \uceec\ub7fc \ubc88\uc5ed / \ud30c\uc77c \uc804\uccb4 \ubc88\uc5ed(\uc2dc\ud2b8\u00b7\uad6c\uc870 \ubcf4\uc874) / \ub2e8\ubb38 \uc989\uc2dc \ubc88\uc5ed, \uc2e4\ud328 \ud589\ub9cc \uc7ac\uc2dc\ub3c4."],["Analyze","\ubd84\uc11d(Analyze)"],["\u2014 Sends each full row to the LLM as JSON. The prompt template uses","\u2014 \ud589 \uc804\uccb4\ub97c JSON\uc73c\ub85c LLM\uc5d0 \ud22c\uc785\ud558\uace0, \ud504\ub86c\ud504\ud2b8 \ud15c\ud50c\ub9bf\uc758"],["placeholders to inject domain context such as document type, contractor and owner.","\ud50c\ub808\uc774\uc2a4\ud640\ub354\ub85c \ubb38\uc11c \uc720\ud615\u00b7\uc2dc\uacf5\uc0ac\u00b7\ubc1c\uc8fc\ucc98 \ub4f1 \ub3c4\uba54\uc778 \ucee8\ud14d\uc2a4\ud2b8\ub97c \uc8fc\uc785."],["Review","\uac80\ud1a0(Review)"],["\u2014 Paginate, search and filter analysis results, then","\u2014 \ubd84\uc11d \uacb0\uacfc \ud398\uc774\uc9c0\ub124\uc774\uc158\u00b7\uac80\uc0c9\u00b7\ud544\ud130, \uc120\ud0dd \ub808\ucf54\ub4dc\ub97c"],["export selected records to Excel/PDF","Excel/PDF\ub85c \ub0b4\ubcf4\ub0b4\uae30"],["Write","\uc791\uc131(Write)"],["\u2014 Generates a Deviation List (proposal, rationale and revised wording) in the role of \u201cLead Proposal Engineer,\u201d chained directly from Analyze results.","\u2014 \"Lead Proposal Engineer\" \uc5ed\ud560\ub85c Deviation List(\uc81c\uc548\u00b7\uc0ac\uc720\u00b7\uc218\uc815\ubb38\uc548)\ub97c \uc0dd\uc131, Analyze \uacb0\uacfc\uc5d0\uc11c \uc9c1\uc811 \uccb4\uc774\ub2dd."],["Analyze screen \u2014 project information, file upload, domain context and a placeholder-based prompt template","Analyze \ud654\uba74 \u2014 \ud504\ub85c\uc81d\ud2b8 \uc815\ubcf4, \ud30c\uc77c \uc5c5\ub85c\ub4dc, \ub3c4\uba54\uc778 \ucee8\ud14d\uc2a4\ud2b8, \ud50c\ub808\uc774\uc2a4\ud640\ub354 \ud504\ub86c\ud504\ud2b8 \ud15c\ud50c\ub9bf"],["Write screen \u2014 Deviation List drafting module","Write \ud654\uba74 \u2014 Deviation List \uc791\uc131 \ubaa8\ub4c8"],["Review screen \u2014 review and export analysis results","Review \ud654\uba74 \u2014 \ubd84\uc11d \uacb0\uacfc \uac80\ud1a0 \ubc0f \ub0b4\ubcf4\ub0b4\uae30"],["Settings screen \u2014 OpenRouter Base URL, API Key and Model settings","Settings \ud654\uba74 \u2014 OpenRouter Base URL \u00b7 API Key \u00b7 Model \uc124\uc815"],["Analyze's placeholder context system (top left), the Write and Review modules, and Settings consolidated around one OpenRouter key. Credentials are stored in a locally encrypted file.","Analyze\uc758 \ud50c\ub808\uc774\uc2a4\ud640\ub354 \ucee8\ud14d\uc2a4\ud2b8 \uc2dc\uc2a4\ud15c(\uc88c\uc0c1), Write\u00b7Review \ubaa8\ub4c8, \uadf8\ub9ac\uace0 \ub2e8\uc77c OpenRouter \ud0a4\ub85c \uc815\ub9ac\ud55c Settings. \uc778\uc99d \uc815\ubcf4\ub294 \ub85c\uceec \uc554\ud638\ud654 \ud30c\uc77c\uc5d0 \uc800\uc7a5\ub429\ub2c8\ub2e4."],["tools over tokens \u2014 LLM orchestration, reliability in code","tools over tokens \u2014 LLM\uc740 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\uc158, \uc2e0\ub8b0\uc131\uc740 \ucf54\ub4dc"],["Industrial domains with little tolerance for errors cannot rely on an LLM alone. DocPilot funnels LLM calls through one thin client (","\uc624\ub958 \ud5c8\uc6a9\uce58\uac00 \ub0ae\uc740 \uc0b0\uc5c5 \ub3c4\uba54\uc778\uc5d0\uc11c LLM\uc744 \uadf8\ub300\ub85c \ubbff\uc744 \uc218\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. DocPilot\uc740 LLM \ud638\ucd9c \uacbd\uacc4\ub97c \uc587\uc740 \ud074\ub77c\uc774\uc5b8\ud2b8 \ud558\ub098("],["), wrapped in a deterministic reliability layer.",")\ub85c \ubaa8\uc73c\uace0, \uadf8 \uc8fc\uc704\ub97c \uacb0\uc815\ub860\uc801 \uc2e0\ub8b0\uc131 \uacc4\uce35\uc73c\ub85c \uac10\uc309\ub2c8\ub2e4."],["Reliable calls","\ud638\ucd9c \uc2e0\ub8b0\uc131"],["A global concurrency semaphore, exponential-backoff retries, 429/Retry-After handling and a typed error taxonomy (AUTH/RATE/TIMEOUT/TRUNCATED/\u2026) turn failures into specific codes.","\uc804\uc5ed \ub3d9\uc2dc\uc131 \uc138\ub9c8\ud3ec\uc5b4, \uc9c0\uc218 \ubc31\uc624\ud504 \uc7ac\uc2dc\ub3c4, 429/Retry-After \ucc98\ub9ac, \ud0c0\uc785\ub4dc \uc5d0\ub7ec taxonomy(AUTH/RATE/TIMEOUT/TRUNCATED/\u2026)\ub85c \uc2e4\ud328\ub97c \uad6c\uccb4\uc801 \ucf54\ub4dc\ub85c \ud658\uc6d0."],["Run recovery","\uc2e4\ud589 \ubcf5\uc6d0"],["The batch runner manages progress and cancellation, restores active runs after a browser refresh, and retries only the rows that failed.","\ubc30\uce58 \uc2e4\ud589\uae30\uac00 \uc9c4\ud589\ub960\u00b7\ucde8\uc18c\ub97c \uad00\ub9ac\ud558\uace0, \ube0c\ub77c\uc6b0\uc800\ub97c \uc0c8\ub85c\uace0\uce68\ud574\ub3c4 \uc9c4\ud589 \uc911\uc774\ub358 run\uc744 \ubcf5\uc6d0. \ubd80\ubd84 \uc2e4\ud328 \ud589\ub9cc \uace8\ub77c \uc7ac\uc2dc\ub3c4."],["Any gateway that follows the OpenAI-compatible schema (","OpenAI \ud638\ud658 \uc2a4\ud0a4\ub9c8("],[", Bearer) works. Switching from the internal LLM gateway to OpenRouter required replacing just this client file.",", Bearer)\ub9cc \uc9c0\ud0a4\uba74 \uc5b4\ub5a4 \uac8c\uc774\ud2b8\uc6e8\uc774\ub4e0 \ubd99\uc2b5\ub2c8\ub2e4 \u2014 \uc0ac\ub0b4 LLM \uac8c\uc774\ud2b8\uc6e8\uc774\uc5d0\uc11c OpenRouter\ub85c\uc758 \uc804\ud658\ub3c4 \uc774 \ud074\ub77c\uc774\uc5b8\ud2b8 \ud55c \ud30c\uc77c \uad50\uccb4\ub85c \ub05d\ub0ac\uc2b5\ub2c8\ub2e4."],["Offline delivery \u2014 run an executable","\uc624\ud504\ub77c\uc778 \ubc30\ud3ec \u2014 \uc124\uce58\uac00 \uc544\ub2c8\ub77c \uc2e4\ud589\ud30c\uc77c"],[" installs dependencies from an offline wheelhouse and uses PyInstaller onedir to build","\uc774 \uc624\ud504\ub77c\uc778 wheelhouse\ub85c \uc758\uc874\uc131\uc744 \uc124\uce58\ud558\uace0 PyInstaller onedir\ub85c"],[". Launching it starts a local FastAPI server at","\ub97c \ub9cc\ub4ed\ub2c8\ub2e4. \uc2e4\ud589\ud558\uba74"],[" and opens the default browser automatically. Secrets are encrypted with Fernet and stored locally; the app communicates externally only with the LLM endpoint. The Python runtime is included in one folder for transfer into an air-gapped environment, without Electron or Tauri.","\uc758 \ub85c\uceec FastAPI \uc11c\ubc84\uac00 \ub728\uace0 \uae30\ubcf8 \ube0c\ub77c\uc6b0\uc800\uac00 \uc790\ub3d9\uc73c\ub85c \uc5f4\ub9bd\ub2c8\ub2e4. \uc2dc\ud06c\ub9bf\uc740 Fernet\uc73c\ub85c \uc554\ud638\ud654\ud574 \ub85c\uceec\uc5d0\ub9cc \uc800\uc7a5\ud558\uace0, \uc571\uc740 LLM \uc5d4\ub4dc\ud3ec\uc778\ud2b8 \uc678\uc5d0\ub294 \uc678\ubd80\uc640 \ud1b5\uc2e0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. Electron/Tauri \uc5c6\uc774, \ud30c\uc774\uc36c \ub7f0\ud0c0\uc784\uae4c\uc9c0 \ud55c \ud3f4\ub354\uc5d0 \ub2f4\uc544 \ud3d0\uc1c4\ub9dd \ubc18\uc785\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4."],["offline wheelhouse","\uc624\ud504\ub77c\uc778 wheelhouse"],["Automatic browser launch","\ube0c\ub77c\uc6b0\uc800 \uc790\ub3d9 \uc624\ud508"],["Fernet-encrypted secrets","Fernet \uc554\ud638\ud654 \uc2dc\ud06c\ub9bf"],["Evolution \u2014 adding a declarative LangGraph agent","\uc9c4\ud654 \u2014 \uc120\uc5b8\uc801 LangGraph \uc5d0\uc774\uc804\ud2b8\ub97c \uc5b9\ub2e4"],["After stabilizing the app, I explored its evolution into an agent in a separate package (","\uc571\uc744 \uc548\uc815\ud654\ud55c \ub4a4, \"\uc774 \uc571\uc744 \uc5b4\ub5bb\uac8c \uc5d0\uc774\uc804\ud2b8\ub85c \uc9c4\ud654\uc2dc\ud0ac\uae4c\"\ub97c \ubcc4\ub3c4 \ud328\ud0a4\uc9c0("],["). It performs",")\ub85c \uc2e4\ud5d8\ud588\uc2b5\ub2c8\ub2e4. EPC \uc0ac\uc591 \uc870\ud56d\uc758"],["deviation reviews of EPC specification clauses","deviation(\uc0ac\uc591 \uc774\ud0c8) \uac80\ud1a0"],[" using a state machine whose complete workflow is","\ub97c, \uc6cc\ud06c\ud50c\ub85c \uc804\uccb4\ub97c"],["declared in YAML","YAML\ub85c \uc120\uc5b8"],[" and compiled with","\ud558\uace0"],[". The deployed app runs without langgraph; the agent is an isolated capability showcase.","\ub85c \ucef4\ud30c\uc77c\ud55c \uc0c1\ud0dc\uba38\uc2e0\uc73c\ub85c \uc218\ud589\ud569\ub2c8\ub2e4. \ubc30\ud3ec \uc571\uc740 langgraph \uc5c6\uc774 \ub3d9\uc791\ud558\uba70, \uc5d0\uc774\uc804\ud2b8\ub294 \uaca9\ub9ac\ub41c \uc5ed\ub7c9 \uc1fc\ucf00\uc774\uc2a4\uc785\ub2c8\ub2e4."],["Agent graph: extract, ambiguity gate, clarify loop, validate, draft, qa gate, output","\uc5d0\uc774\uc804\ud2b8 \uadf8\ub798\ud504: extract, ambiguity gate, clarify \ub8e8\ud504, validate, draft, qa gate, output"],["extract (LLM)","extract (LLM \ucd94\ucd9c)"],["ambiguity gate","\ubaa8\ud638\uc131 \uac8c\uc774\ud2b8"],["clarify \u21bb (self-correction)","clarify \u21bb (\uc790\uac00\ubcf4\uc815)"],["validate (deterministic)","validate (\uacb0\uc815\ub860)"],["draft","\ucd08\uc548 \uc791\uc131"],["qa gate","\ud488\uc9c8 \uac8c\uc774\ud2b8"],["output","\ucd9c\ub825"],["LLM node","LLM \ub178\ub4dc"],["Deterministic tool / gate","\uacb0\uc815\ub860 \ub3c4\uad6c/\uac8c\uc774\ud2b8"],["Transparent flag","\uc815\uc9c1\ud55c \ud50c\ub798\uadf8"],["Named routers return branch labels only; the final","\ubd84\uae30\ub294 named \ub77c\uc6b0\ud130\uac00 \ub77c\ubca8\ub9cc \ubc18\ud658\ud558\uace0, \uc885\ub8cc"],[" is always written by a deterministic node. Ambiguity triggers a","\ub294 \ud56d\uc0c1 \uacb0\uc815\ub860 \ub178\ub4dc\uac00 \uc501\ub2c8\ub2e4. \uc560\ub9e4\ud558\uba74"],["loop (up to 2 attempts by default). If exhausted, the agent reports","\ub8e8\ud504(\uae30\ubcf8 \ucd5c\ub300 2\ud68c), \uc18c\uc9c4\ub418\uba74"],[" transparently, without manufacturing certainty.","\ub85c \uc815\uc9c1\ud558\uac8c \ud50c\ub798\uadf8\ud569\ub2c8\ub2e4 \u2014 \uac00\uc9dc \ud655\uc2e0\uc744 \ub9cc\ub4e4\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."],["The traces below are from actual OpenRouter smoke-test runs.","\uc544\ub798\ub294 \uc2e4\uc81c OpenRouter \uc2e4\ud589 \ud2b8\ub808\uc774\uc2a4\uc785\ub2c8\ub2e4(\uc2a4\ubaa8\ud06c \ud14c\uc2a4\ud2b8 \uc2e4\uce21)."],["$ python -m agents.run --input samples/validation_fail.json \u00b7 Clause citing GB/T 700 as its sole standard","$ python -m agents.run --input samples/validation_fail.json \u00b7 GB/T 700 \uc744 \uc720\uc77c \ud45c\uc900\uc73c\ub85c \uc778\uc6a9\ud55c \uc870\ud56d"],["\u2514 The deterministic tool rejects the unapproved standard, skips draft and exits","\u2514 \uacb0\uc815\ub860 \ub3c4\uad6c\uac00 \ubbf8\uc2b9\uc778 \ud45c\uc900\uc744 \uc7a1\uc544 draft\ub97c \uac74\ub108\ub6f0\uace0 \uc885\ub8cc"],["$ python -m agents.run --input samples/ambiguous_clause.json \u00b7 An ambiguous clause such as \u201csuitable alternative materials may be used\u201d","$ python -m agents.run --input samples/ambiguous_clause.json \u00b7 \"\uc801\uc808\ud55c \ub300\uccb4 \uc7ac\ub8cc\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4\"\ub958 \ubaa8\ud638 \uc870\ud56d"],["\u2514 Still unresolved after 2 attempts \u2192 flagged for human review instead of forcing a conclusion","\u2514 2\ud68c \ubcf4\uc815\uc5d0\ub3c4 \ud574\uc18c \uc548 \ub428 \u2192 \uc5b5\uc9c0 \uacb0\ub860 \ub300\uc2e0 \uc0ac\ub78c \uac80\ud1a0\ub85c \ud50c\ub798\uadf8"],["Agent code \u00b7 YAML \u00b7 tests \u2192","\uc5d0\uc774\uc804\ud2b8 \ucf54\ub4dc\u00b7YAML\u00b7\ud14c\uc2a4\ud2b8 \u2192"],["The trajectory of one project","\ud55c \ud504\ub85c\uc81d\ud2b8\uac00 \uadf8\ub824\uc628 \uada4\uc801"],["The same problem, refined over time beyond a short-lived demo.","\ub2e8\uae30\uac04\uc758 \ub370\ubaa8\uac00 \uc544\ub2c8\ub77c, \uac19\uc740 \ubb38\uc81c\ub97c \uacc4\uc18d \ub2e4\ub4ec\uc5b4 \uc654\uc2b5\ub2c8\ub2e4."],["Original internal competition entry \u2014 a PyQt5 desktop prototype with 4 document tools.","\uc0ac\ub0b4 \uacbd\uc9c4\ub300\ud68c \ucd9c\ud488\uc791 \uc6d0\ubcf8 \u2014 PyQt5 \ub370\uc2a4\ud06c\ud1b1 \ud504\ub85c\ud1a0\ud0c0\uc785, 4\uac1c \ubb38\uc11c \ub3c4\uad6c."],["Problem definition and the first working version.","\ubb38\uc81c \uc815\uc758\uc640 \uccab \ub3d9\uc791\ud558\ub294 \ubc84\uc804."],["Full-stack rebuild \u2014 FastAPI + React + SQLite, a PyInstaller exe, module chaining and a reliability layer.","\ud480\uc2a4\ud0dd rebuild \u2014 FastAPI + React + SQLite, PyInstaller exe, \ubaa8\ub4c8 \uccb4\uc774\ub2dd\uacfc \uc2e0\ub8b0\uc131 \uacc4\uce35."],["From a prototype to a deployable product structure.","\ud504\ub85c\ud1a0\ud0c0\uc785\uc744 \ubc30\ud3ec \uac00\ub2a5\ud55c \uc81c\ud488 \uad6c\uc870\ub85c."],["Added a LangGraph/YAML agent \u2014 specification-deviation reviews as a declarative state machine.","LangGraph/YAML \uc5d0\uc774\uc804\ud2b8 \ucd94\uac00 \u2014 \uc0ac\uc591 deviation \uac80\ud1a0\ub97c \uc120\uc5b8\uc801 \uc0c1\ud0dc\uba38\uc2e0\uc73c\ub85c."],["Evolving the app into an agent.","\uc571\uc744 \uc5d0\uc774\uc804\ud2b8\ub85c \uc9c4\ud654."],["Why this project \u2014 limitations and next steps","\uc65c \uc774 \ud504\ub85c\uc81d\ud2b8\uc778\uac00 \u2014 \ud55c\uacc4\uc640 \ub2e4\uc74c"],["Through actual deployment","\uc2e4\uc81c \ubc30\ud3ec\uae4c\uc9c0"],["\u2014 A full-stack app built and deployed as a single exe for air-gapped environments, beyond a prototype.","\u2014 \ud504\ub85c\ud1a0\ud0c0\uc785\uc774 \uc544\ub2c8\ub77c \ub2e8\uc77c exe\ub85c \ube4c\ub4dc\u00b7\ubc30\ud3ec\ub41c, \ud3d0\uc1c4\ub9dd\uc5d0\uc11c \ub3c4\ub294 \ud480\uc2a4\ud0dd \uc571."],["\u2014 A reliability layer and deterministic gates that preserve verifiability in the LLM era.","\u2014 LLM \uc2dc\ub300\uc5d0 \uac80\uc99d \uac00\ub2a5\uc131\uc744 \uc9c0\ud0a4\ub294 \uc2e0\ub8b0\uc131 \uacc4\uce35\uacfc \uacb0\uc815\ub860 \uac8c\uc774\ud2b8."],["Declarative orchestration","\uc120\uc5b8\uc801 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\uc158"],["\u2014 Workflows declared in YAML and compiled with langgraph, with ambiguity branches, self-correction and transparent flags.","\u2014 \uc6cc\ud06c\ud50c\ub85c\ub97c YAML\ub85c \uc120\uc5b8\ud558\uace0 langgraph\ub85c \ucef4\ud30c\uc77c, \uc560\ub9e4 \ubd84\uae30\u00b7\uc790\uac00\ubcf4\uc815\u00b7\uc815\uc9c1\ud55c \ud50c\ub798\uadf8."],["Limitations: standard-reference validation for deviation reviews uses only an illustrative demo set (ASME/ASTM/API/ISO/EN/ANSI), and the agent has few samples. Next: connect a standards-reference database, extend workflows by document type, and revalidate with an internal gateway.","\ud55c\uacc4: deviation \uac80\ud1a0\uc758 \ud45c\uc900 \ucc38\uc870 \uac80\uc99d\uc740 \ub370\ubaa8\uc6a9 illustrative set(ASME/ASTM/API/ISO/EN/ANSI) \uc218\uc900\uc774\uace0, \uc5d0\uc774\uc804\ud2b8 \uc0d8\ud50c\uc740 \uc18c\uc218\uc785\ub2c8\ub2e4. \ub2e4\uc74c: \ud45c\uc900 \ucc38\uc870 DB \uc5f0\uacb0, \ubb38\uc11c \uc720\ud615\ubcc4 \uc6cc\ud06c\ud50c\ub85c \ud655\uc7a5, \uc0ac\ub0b4 \uac8c\uc774\ud2b8\uc6e8\uc774 \ud658\uacbd\uc5d0\uc11c\uc758 \uc7ac\uac80\uc99d."],["GitHub repository (app, agent and all documentation)","GitHub \ub808\ud3ec (\uc571\u00b7\uc5d0\uc774\uc804\ud2b8\u00b7\ubb38\uc11c \uc804\uccb4)"],["LangGraph agent","LangGraph \uc5d0\uc774\uc804\ud2b8"],["\u2190 Portfolio home","\u2190 \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ud648"],["\u00a9 2026 Jinhyun An \u00b7 DocPilot \u2014 anonymized public portfolio version \u00b7 Screenshots from the running app; traces measured with OpenRouter","\u00a9 2026 Jinhyun An \u00b7 DocPilot \u2014 \uc775\uba85\ud654\ub41c \uacf5\uac1c \ud3ec\ud2b8\ud3f4\ub9ac\uc624 \ubc84\uc804 \u00b7 \ud654\uba74\uc740 \uc2e4\uc81c \uc571 \uad6c\ub3d9 \ucea1\ucc98, \ud2b8\ub808\uc774\uc2a4\ub294 OpenRouter \uc2e4\uce21"]];
